talker() {
    if (!this.payload) {
        throw new Error('no payload');
    }
    let talkerId = this.payload.talkerId;
    ...
    let talker;
    if (this.wechaty.isLoggedIn && talkerId === this.wechaty.puppet.currentUserId) {
        talker = this.wechaty.ContactSelf.load(talkerId);
    }
    else {
        talker = this.wechaty.Contact.load(talkerId);
    }
    return talker;
